import unittest

from hourglass.rounding import (
    describe_span,
    label_spans,
    round_span
)
from hourglass.parsing import parse_span
from hourglass.models import Span

class RoundSpanTests(unittest.TestCase):
    def test_rounds_to_nearest(self):
        span = parse_span("08:53-17:08")
        self.assertEqual(
            round_span(span, 15), parse_span("09:00-17:15")
        )

    def test_halves_round_up(self):
        result = round_span(Span(555, 1035), 30)
        self.assertEqual(result, Span(570, 1050))

    def test_exact_times_stay(self):
        span = parse_span("09:00-17:30")
        self.assertEqual(round_span(span, 30), span)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(parse_span("09:00-09:05"), 15)

class LabelTests(unittest.TestCase):
    def test_describe(self):
        span = parse_span("09:00-17:15")
        self.assertEqual(
            describe_span(span), "09:00-17:15 (8h 15m)"
        )

    def test_labels_each_span(self):
        spans = [parse_span("08:58-12:01"), Span(750, 1020)]
        self.assertEqual(
            label_spans(spans, 15),
            ["09:00-12:00 (3h 0m)", "12:30-17:00 (4h 30m)"]
        )

    def test_empty_list(self):
        self.assertEqual(label_spans([], 15), [])

    def test_step_of_one_changes_nothing(self):
        span = parse_span("09:07-10:11")
        self.assertEqual(round_span(span, 1), span)

class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        span = Span(540, 600)
        for step in (0, -15, 7, 45, 90, 7.5, "15"):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_spans([span], step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            label_spans([], 0)

    def test_good_steps_accepted(self):
        span = Span(540, 600)
        for step in (1, 5, 6, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                result = round_span(span, step)
                self.assertEqual(result, span)
